{"formatVersion":3,"title":"Метка на холсте","description":"Один холст с рамкой: касание ставит оранжевую метку в точке касания, показывает число касаний и сбрасывается кнопкой «Сбросить».","capabilities":[],"capabilityResults":false,"presentation":{"mode":"immersive"},"surfaces":[{"id":"main","width":360,"height":640,"sizing":"viewport"}],"stateSchema":{"count":"number","hasMark":"boolean","nx":"number","ny":"number","vw":"number","vh":"number"},"initialState":{"count":0,"hasMark":false,"nx":0.5,"ny":0.5,"vw":360,"vh":640},"behaviorBindings":{"surface":"main","marker":{"surface":"main","path":[2]},"count":[0],"reset":"reset"},"ui":{"type":"column","style":{"padding":"medium","gap":"small"},"children":[{"type":"metric","text":"Касаний","bind":"count","format":"number","style":{"emphasis":"number"}},{"type":"button","text":"Сбросить","action":"reset","variant":"tonal"},{"type":"text","text":"Коснитесь холста, чтобы поставить метку."}]},"source":"const event = input.event || {};
const s = Object.assign({}, input.state);
let vw = Number(s.vw);
if (!isFinite(vw) || vw <= 0) vw = 360;
let vh = Number(s.vh);
if (!isFinite(vh) || vh <= 0) vh = 640;
const type = event.type;
if (type === 'viewport' && event.surfaceId === 'main') {
  const w = Number(event.width);
  const h = Number(event.height);
  if (isFinite(w) && w >= 64 && w <= 2048) { s.vw = w; vw = w; }
  if (isFinite(h) && h >= 64 && h <= 2048) { s.vh = h; vh = h; }
} else if (type === 'pointer' && event.surfaceId === 'main' && event.phase === 'down' && event.pointer === 0) {
  let x = Number(event.x);
  let y = Number(event.y);
  if (!isFinite(x)) x = vw / 2;
  if (!isFinite(y)) y = vh / 2;
  s.nx = Math.min(1, Math.max(0, x / vw));
  s.ny = Math.min(1, Math.max(0, y / vh));
  s.count = (Number(s.count) || 0) + 1;
  s.hasMark = true;
} else if (type === 'action' && event.actionId === 'reset') {
  s.count = 0;
  s.hasMark = false;
}
const width = vw;
const height = vh;
const hasMark = s.hasMark === true;
const nx = Math.min(1, Math.max(0, Number(s.nx) || 0));
const ny = Math.min(1, Math.max(0, Number(s.ny) || 0));
const mx = nx * width;
const my = ny * height;
const count = Math.max(0, Math.round(Number(s.count) || 0));
const outerR = hasMark ? 18 : 0;
const innerR = hasMark ? 6 : 0;
const commands = [
  {type: 'rect', x: 0, y: 0, width: width, height: height, color: '#F1F3F4'},
  {type: 'roundRect', x: 10, y: 10, width: Math.max(1, width - 20), height: Math.max(1, height - 20), radius: 18, stroke: 2, color: 'muted'},
  {type: 'group', children: [
    {type: 'circle', x: mx, y: my, radius: outerR, color: '#FF7A00'},
    {type: 'circle', x: mx, y: my, radius: innerR, color: '#FFFFFFFF'}
  ]},
  {type: 'text', x: 24, y: 60, size: 44, text: String(count), color: '#FF202124'},
  {type: 'text', x: 24, y: 84, size: 14, text: 'Касаний', color: '#FF5F6368'}
];
const ui = {
  type: 'column',
  style: {padding: 'medium', gap: 'small'},
  children: [
    {type: 'metric', text: 'Касаний', bind: 'count', format: 'number', style: {emphasis: 'number'}},
    {type: 'button', text: 'Сбросить', action: 'reset', variant: 'tonal'},
    {type: 'text', text: 'Коснитесь холста, чтобы поставить метку.'}
  ]
};
return {state: s, ui: ui, surfaces: {main: {commands: commands}}};"}
